# -*- coding: utf-8 -*-
"""sci_progress.py — 课题进展统筹 v0（Phase 3a）

目录约定（指导书附录 A）：
  projects/sci-assistant/progress/<project-slug>/
    project.yaml                课题元数据 + 里程碑 + 实验索引
    log/YYYY-MM-DD-<exp-id>.md  实验日志（frontmatter + 正文）
    progress.md                 自动生成的进展摘要

用法：
  python tools/sci_progress.py new "LFP 再生" --direction 电解液设计 --entry "AI 电解质设计"
  python tools/sci_progress.py list
  python tools/sci_progress.py show lfp-再生
  python tools/sci_progress.py log lfp-再生 --title "首轮筛选" --body "..." --result partial
  python tools/sci_progress.py milestone lfp-再生 --add "完成首轮筛选"
  python tools/sci_progress.py milestone lfp-再生 --done 1
  python tools/sci_progress.py status lfp-再生 running
  python tools/sci_progress.py link lfp-再生 --protocol "protocols/锌-电解液/strategy.md"
  python tools/sci_progress.py summary lfp-再生
  python tools/sci_progress.py --selftest

🔴 写盘纪律：project.yaml 用 yaml.safe_dump 写、写完 yaml.safe_load 复算；
   日志文件名冲突自动加后缀，不覆盖既有记录。
"""

import argparse
import datetime
import json
import os
import re
import sys

TOOLS_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, TOOLS_DIR)

import kb_lib as K  # noqa: E402
K.console_encoding()

CONFIG_REL = "projects/sci-assistant/config/sci_assistant_config.yaml"
STATUSES = ("planned", "running", "paused", "done")
RESULTS = ("success", "failed", "partial", "unknown")
RESULT_ZH = {"success": "成功", "failed": "失败", "partial": "部分", "unknown": "未标注"}


# ---------------------------------------------------------------- 配置 / 路径

def load_config(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, CONFIG_REL)
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def progress_root(cfg):
    rel = (cfg.get("sci") or {}).get("progress_dir") or "projects/sci-assistant/progress"
    return rel if os.path.isabs(rel) else os.path.join(K.VAULT, rel)


def slugify(s):
    s = re.sub(r'[<>:"/\\|?*\s]+', "-", str(s or "").strip())
    return s.strip("-.") or "project"


def project_dir(cfg, slug):
    return os.path.join(progress_root(cfg), slug)


def project_path(cfg, slug):
    return os.path.join(project_dir(cfg, slug), "project.yaml")


# ---------------------------------------------------------------- 读写

def _read_yaml(path):
    import yaml
    with open(path, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def _write_yaml(path, data):
    import yaml
    text = yaml.safe_dump(data, allow_unicode=True, sort_keys=False,
                          default_flow_style=False)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    # 写后复算
    back = _read_yaml(path)
    if back.get("title") != data.get("title"):
        raise SystemExit(f"[!] project.yaml 写盘复算失败: {path}")
    return path


def load_project(cfg, slug):
    p = project_path(cfg, slug)
    if not os.path.isfile(p):
        raise SystemExit(f"[!] 课题不存在: {slug}（先 new）")
    return _read_yaml(p)


def save_project(cfg, slug, data):
    data["updated"] = datetime.date.today().isoformat()
    return _write_yaml(project_path(cfg, slug), data)


def _today():
    return datetime.date.today().isoformat()


# ---------------------------------------------------------------- 课题操作

def new_project(cfg, title, direction="", entry="", goal="", slug=None, status="planned"):
    slug = slug or slugify(title)
    p = project_path(cfg, slug)
    if os.path.isfile(p):
        raise SystemExit(f"[!] 课题目录已存在: {slug}")
    data = {
        "title": title,
        "slug": slug,
        "status": status if status in STATUSES else "planned",
        "direction": direction,
        "entry_point": entry,
        "goal": goal,
        "created": _today(),
        "updated": _today(),
        "protocol_refs": [],
        "milestones": [],
        "experiments": [],
    }
    save_project(cfg, slug, data)
    os.makedirs(os.path.join(project_dir(cfg, slug), "log"), exist_ok=True)
    return data


def add_milestone(cfg, slug, title):
    data = load_project(cfg, slug)
    data.setdefault("milestones", []).append({
        "id": len(data["milestones"]) + 1, "title": title,
        "done": False, "added": _today(), "done_date": "",
    })
    save_project(cfg, slug, data)
    return data["milestones"][-1]


def complete_milestone(cfg, slug, mid):
    data = load_project(cfg, slug)
    for m in data.get("milestones") or []:
        if int(m.get("id")) == int(mid):
            m["done"] = True
            m["done_date"] = _today()
            save_project(cfg, slug, data)
            return m
    raise SystemExit(f"[!] 没有里程碑 #{mid}")


def link_protocol(cfg, slug, ref):
    data = load_project(cfg, slug)
    refs = data.setdefault("protocol_refs", [])
    if ref not in refs:
        refs.append(ref)
    save_project(cfg, slug, data)
    return refs


def set_status(cfg, slug, status):
    if status not in STATUSES:
        raise SystemExit(f"[!] 状态只能是 {STATUSES}")
    data = load_project(cfg, slug)
    data["status"] = status
    save_project(cfg, slug, data)
    return status


def _exp_id(data):
    return "E%03d" % (len(data.get("experiments") or []) + 1)


def add_log(cfg, slug, title, body="", date=None, result="unknown",
            tags=None, data_paths=None):
    """写一篇实验日志；返回 (log 相对路径, experiment 记录)。"""
    if result not in RESULTS:
        raise SystemExit(f"[!] result 只能是 {RESULTS}")
    data = load_project(cfg, slug)
    date = date or _today()
    exp_id = _exp_id(data)
    log_dir = os.path.join(project_dir(cfg, slug), "log")
    os.makedirs(log_dir, exist_ok=True)
    fname = f"{date}-{exp_id}.md"
    path = os.path.join(log_dir, fname)
    n = 2
    while os.path.exists(path):          # 不覆盖既有日志
        fname = f"{date}-{exp_id}-{n}.md"
        path = os.path.join(log_dir, fname)
        n += 1
    import yaml
    fm = {
        "type": "experiment",
        "date": date, "project": slug, "exp_id": exp_id,
        "title": title, "result": result,
        "tags": tags or [], "data": data_paths or [],
        "created": _today(),
    }
    text = ("---\n" + yaml.safe_dump(fm, allow_unicode=True, sort_keys=False,
                                      default_flow_style=False) + "---\n\n"
            + (body or "").rstrip() + "\n")
    K.write_text_verified(path, text, require_frontmatter=True)
    rec = {"exp_id": exp_id, "date": date, "title": title,
           "file": os.path.relpath(path, project_dir(cfg, slug)).replace("\\", "/"),
           "result": result}
    data.setdefault("experiments", []).append(rec)
    save_project(cfg, slug, data)
    return rec


def list_projects(cfg):
    root = progress_root(cfg)
    out = []
    if not os.path.isdir(root):
        return out
    for slug in sorted(os.listdir(root)):
        p = os.path.join(root, slug, "project.yaml")
        if not os.path.isfile(p):
            continue
        try:
            d = _read_yaml(p)
        except Exception:
            continue
        out.append({"slug": slug, "title": d.get("title"), "status": d.get("status"),
                    "experiments": len(d.get("experiments") or []),
                    "milestones": len(d.get("milestones") or []),
                    "milestones_done": sum(1 for m in d.get("milestones") or []
                                           if m.get("done")),
                    "updated": d.get("updated")})
    return out


# ---------------------------------------------------------------- 摘要

def render_summary(data):
    exps = data.get("experiments") or []
    ms = data.get("milestones") or []
    done = sum(1 for m in ms if m.get("done"))
    res = {}
    for e in exps:
        res[e.get("result") or "unknown"] = res.get(e.get("result") or "unknown", 0) + 1
    L = [f"# 进展摘要：{data.get('title')}", ""]
    L.append(f"> slug：`{data.get('slug')}` ｜ 状态：**{data.get('status')}** ｜ "
             f"创建：{data.get('created')} ｜ 更新：{data.get('updated')}")
    L.append("")
    L.append("## 概况")
    L.append("")
    L.append(f"- 方向：{data.get('direction') or '—'}")
    L.append(f"- 切入点：{data.get('entry_point') or '—'}")
    if data.get("goal"):
        L.append(f"- 目标：{data['goal']}")
    L.append(f"- 实验记录：**{len(exps)}** 篇（" +
             "、".join(f"{RESULT_ZH.get(k, k)} {v}" for k, v in sorted(res.items())) + "）"
             if exps else "- 实验记录：**0** 篇")
    L.append(f"- 里程碑：**{done}/{len(ms)}** 完成")
    if data.get("protocol_refs"):
        L.append("- 关联方案：" + "、".join(f"`{r}`" for r in data["protocol_refs"]))
    L.append("")
    L.append("## 里程碑")
    L.append("")
    if ms:
        L.append("| # | 里程碑 | 状态 | 完成日期 |")
        L.append("|---|---|---|---|")
        for m in ms:
            L.append(f"| {m.get('id')} | {m.get('title')} | "
                     f"{'✅' if m.get('done') else '⬜'} | {m.get('done_date') or '—'} |")
    else:
        L.append("（尚未设置里程碑）")
    L.append("")
    L.append("## 最近实验")
    L.append("")
    if exps:
        L.append("| 日期 | ID | 标题 | 结果 | 文件 |")
        L.append("|---|---|---|---|---|")
        for e in exps[-5:][::-1]:
            L.append(f"| {e.get('date')} | {e.get('exp_id')} | {e.get('title')} | "
                     f"{RESULT_ZH.get(e.get('result'), e.get('result'))} | `{e.get('file')}` |")
    else:
        L.append("（还没有实验记录）")
    L.append("")
    L.append("## 下一步")
    L.append("")
    pending = [m for m in ms if not m.get("done")]
    if pending:
        for m in pending:
            L.append(f"- [ ] {m.get('title')}")
    else:
        L.append("- 里程碑已全部完成：可进入成果输出（论文/报告）。")
    L.append("")
    return "\n".join(L)


def write_summary(cfg, slug):
    data = load_project(cfg, slug)
    md = render_summary(data)
    p = os.path.join(project_dir(cfg, slug), "progress.md")
    K.write_text_verified(p, md + "\n")
    return p, md


# ---------------------------------------------------------------- 自检

def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    tmp = K.make_temp_dir(prefix="sci_progress_")
    try:
        cfg = {"sci": {"progress_dir": os.path.join(tmp, "progress")}}
        d = new_project(cfg, "测试课题", direction="电解液设计",
                        entry="AI 电解质设计", goal="验证 X")
        chk("新建：project.yaml 生成且字段正确",
            d["slug"] == "测试课题" and d["status"] == "planned" and
            os.path.isfile(project_path(cfg, d["slug"])))
        chk("新建：yaml 可被 safe_load 解析",
            _read_yaml(project_path(cfg, d["slug"]))["title"] == "测试课题")

        m1 = add_milestone(cfg, d["slug"], "完成首轮筛选")
        add_milestone(cfg, d["slug"], "第二个里程碑")
        chk("里程碑：新增两条且 id 递增",
            m1["id"] == 1 and len(load_project(cfg, d["slug"])["milestones"]) == 2)
        done = complete_milestone(cfg, d["slug"], 1)
        chk("里程碑：完成标记与日期", done["done"] is True and done["done_date"])

        r1 = add_log(cfg, d["slug"], "首轮筛选", "结果：3 个候选", result="partial",
                     tags=["筛选"], data_paths=["data/raw.csv"])
        p1 = os.path.join(project_dir(cfg, d["slug"]), r1["file"])
        txt = K.read_text(p1)
        chk("日志：文件生成且带 frontmatter",
            txt.startswith("---\n") and "exp_id: E001" in txt and "首轮筛选" in txt)
        rec = _read_yaml_front(txt)
        chk("日志：frontmatter 字段完整",
            rec.get("result") == "partial" and rec.get("date") and
            rec.get("data") == ["data/raw.csv"])
        r2 = add_log(cfg, d["slug"], "第二轮", "结果：失败", result="failed")
        chk("日志：exp_id 递增", r2["exp_id"] == "E002")
        # 同日同名不覆盖
        r3 = add_log(cfg, d["slug"], "第二轮", "重复写入", date=r2["date"])
        chk("日志：同名文件不覆盖", r3["file"] != r2["file"])

        set_status(cfg, d["slug"], "running")
        chk("状态：可切换为 running",
            load_project(cfg, d["slug"])["status"] == "running")

        link_protocol(cfg, d["slug"], "protocols/锌-电解液/strategy.md")
        chk("方案关联：去重写入",
            load_project(cfg, d["slug"])["protocol_refs"] ==
            ["protocols/锌-电解液/strategy.md"])

        p, md = write_summary(cfg, d["slug"])
        chk("摘要：含里程碑进度与实验表",
            "1/2" in md and "E002" in md and "失败" in md)
        chk("摘要：含下一步待办", "- [ ] 第二个里程碑" in md)

        lst = list_projects(cfg)
        chk("列表：统计实验数与里程碑完成数",
            len(lst) == 1 and lst[0]["experiments"] == 3 and
            lst[0]["milestones_done"] == 1)
    finally:
        K.remove_temp_dir(tmp)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


def _read_yaml_front(txt):
    import yaml
    raw, _ = K.split_frontmatter(txt)
    return yaml.safe_load(raw) or {}


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="课题进展统筹（Phase 3a）")
    sub = ap.add_subparsers(dest="cmd")

    p_new = sub.add_parser("new", help="新建课题")
    p_new.add_argument("title")
    p_new.add_argument("--direction", default="")
    p_new.add_argument("--entry", default="")
    p_new.add_argument("--goal", default="")
    p_new.add_argument("--slug", default=None)

    sub.add_parser("list", help="列出课题")
    p_show = sub.add_parser("show", help="查看课题")
    p_show.add_argument("slug")

    p_log = sub.add_parser("log", help="新增实验日志")
    p_log.add_argument("slug")
    p_log.add_argument("--title", required=True)
    p_log.add_argument("--body", default="")
    p_log.add_argument("--body-file", default=None)
    p_log.add_argument("--date", default=None)
    p_log.add_argument("--result", default="unknown", choices=RESULTS)
    p_log.add_argument("--tags", default="")
    p_log.add_argument("--data", default="")

    p_ms = sub.add_parser("milestone", help="里程碑")
    p_ms.add_argument("slug")
    p_ms.add_argument("--add", default=None)
    p_ms.add_argument("--done", type=int, default=None)

    p_st = sub.add_parser("status", help="改状态")
    p_st.add_argument("slug")
    p_st.add_argument("status", choices=STATUSES)

    p_lk = sub.add_parser("link", help="关联方案")
    p_lk.add_argument("slug")
    p_lk.add_argument("--protocol", required=True)

    p_sm = sub.add_parser("summary", help="生成进展摘要")
    p_sm.add_argument("slug")
    p_sm.add_argument("--json", action="store_true")

    ap.add_argument("--selftest", action="store_true")
    # --selftest 放在顶层时，subparsers 可能先抢；两者都支持
    args, _unknown = ap.parse_known_args(argv)
    if args.selftest:
        return _selftest()
    if not args.cmd:
        ap.print_help()
        return 1

    cfg = load_config()
    if args.cmd == "new":
        d = new_project(cfg, args.title, args.direction, args.entry,
                        args.goal, args.slug)
        print(f"[ok] 新建课题：{d['slug']}（{d['status']}）")
        return 0
    if args.cmd == "list":
        rows = list_projects(cfg)
        if not rows:
            print("（还没有课题）")
        for r in rows:
            print(f"- {r['slug']} ｜ {r['status']} ｜ 实验 {r['experiments']} ｜ "
                  f"里程碑 {r['milestones_done']}/{r['milestones']} ｜ 更新 {r['updated']}")
        return 0
    if args.cmd == "show":
        d = load_project(cfg, args.slug)
        print(render_summary(d))
        return 0
    if args.cmd == "log":
        body = args.body
        if args.body_file:
            body = K.read_text(args.body_file)
        tags = [t.strip() for t in args.tags.split(",") if t.strip()]
        paths = [p.strip() for p in args.data.split(",") if p.strip()]
        rec = add_log(cfg, args.slug, args.title, body, args.date,
                      args.result, tags, paths)
        print(f"[ok] 日志：{rec['exp_id']} {rec['date']} → {rec['file']}")
        return 0
    if args.cmd == "milestone":
        if args.add:
            m = add_milestone(cfg, args.slug, args.add)
            print(f"[ok] 里程碑 #{m['id']}：{m['title']}")
        if args.done is not None:
            m = complete_milestone(cfg, args.slug, args.done)
            print(f"[ok] 里程碑 #{m['id']} 已完成（{m['done_date']}）")
        if not args.add and args.done is None:
            for m in load_project(cfg, args.slug).get("milestones") or []:
                print(f"  #{m['id']} {'✅' if m['done'] else '⬜'} {m['title']}")
        return 0
    if args.cmd == "status":
        set_status(cfg, args.slug, args.status)
        print(f"[ok] 状态 → {args.status}")
        return 0
    if args.cmd == "link":
        refs = link_protocol(cfg, args.slug, args.protocol)
        print(f"[ok] 已关联（{len(refs)} 条）")
        return 0
    if args.cmd == "summary":
        p, md = write_summary(cfg, args.slug)
        if args.json:
            print(json.dumps(load_project(cfg, args.slug), ensure_ascii=False, indent=2))
        print(f"[ok] 摘要：{os.path.relpath(p, K.VAULT)}")
        return 0
    ap.print_help()
    return 1


if __name__ == "__main__":
    sys.exit(main())
